#!/usr/bin/env bash
# UI test run (PlayMode, GFX=1 for screenshots).   GFX=1 Tools/ui_run.sh <logname> <TestFilter>
# NOBURST=1 adds -burst-disable-compilation (slow: the ground textures are generated by Burst jobs).
HERE="$(cd "$(dirname "$0")" && pwd)"; ROOT="$(cd "$HERE/.." && pwd)"
NAME="${1:?name}"; FILTER="${2:-UiTests}"
XMLW="$(cygpath -w "$ROOT/Logs/cli/$NAME.xml")"; rm -f "$ROOT/Logs/cli/$NAME.xml"
EXTRA=(); [ "${NOBURST:-0}" = "1" ] && EXTRA+=(-burst-disable-compilation)
NOQUIT=1 "$HERE/ub.sh" "$NAME" - -runTests -testPlatform PlayMode -testResults "$XMLW" -testFilter "$FILTER" "${EXTRA[@]}"
python -I "$HERE/test_summary.py" "$ROOT/Logs/cli/$NAME.xml" ${VERBOSE:+-v}
